def _validate_braces(self):
    '''Validate that all braces are properly matched.

    Every opening brace { must have a corresponding closing brace }.
    Escaped braces {{ and }} are ignored.
    '''
    depth = 0
    i = 0
    while i < len(self._format):
        if self._format[i:i+2] == '{{':
            i += 2
            continue
        elif self._format[i:i+2] == '}}':
            i += 2
            continue
        elif self._format[i] == '{':
            depth += 1
        elif self._format[i] == '}':
            depth -= 1
            if depth < 0:
                raise ValueError('unmatched } in format string')
        i += 1
    if depth != 0:
        raise ValueError('unmatched { in format string')

